$ cat Cross.java
public class Cross {
    static Object[] oldArray;
    public static void main(String[] a) throws Exception {
        boolean cross = a[0].equals("cross");
        int N = 1_000_000;
        oldArray = new Object[N];
        for (int i = 0; i < N; i++) oldArray[i] = "x";
        for (int i = 0; i < 15; i++) { System.gc(); Thread.sleep(30); }   // 올드로 보낸다

        Object[] youngArray = new Object[N];        // 갓 만든 배열
        for (int r = 0; r < 40; r++) {
            Object[] target = cross ? oldArray : youngArray;
            for (int i = 0; i < N; i++) target[i] = new byte[16];
        }
    }
}

# 만드는 객체 수도, 참조를 쓰는 횟수도 같다. 쓰는 자리만 다르다.

